'use strict';
const PRIORITIES={q1:'Quan trọng & khẩn cấp · Làm trước',q2:'Quan trọng, không khẩn cấp · Lên lịch',q3:'Khẩn cấp, ít quan trọng · Ủy quyền',q4:'Không quan trọng, không khẩn cấp · Để sau'};
function visibleProjects(){return data.projects.filter(p=>!p.archived).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned));}
function priorityOptions(v){return '<option value="">Chưa phân loại</option>'+Object.entries(PRIORITIES).map(([k,n])=>`<option value="${k}" ${v===k?'selected':''}>${n}</option>`).join('');}
function scheduleFields(t={}){return `<p class="help-copy">Lịch theo giờ Việt Nam</p><div class="fields-row">${field('Bắt đầu','start',t?.start||'','datetime-local')}${field('Kết thúc','end',t?.end||'','datetime-local')}</div>`;}

function archivePage(){return heading('KHO LƯU TRỮ','Dự án đã lưu trữ','Dữ liệu vẫn được giữ, có thể khôi phục bất cứ lúc nào.')+data.projects.filter(p=>p.archived).map(p=>`<section class="panel"><h3>${esc(p.name)}</h3><button class="btn" data-project="${p.id}">Xem dự án</button><button class="btn" data-project-archive="${p.id}">Khôi phục</button></section>`).join('');}
function notesPage(){return heading('KHÔNG GIAN Ý TƯỞNG','Ghi chú','Gom ý tưởng thành các thẻ, phân nhóm và sắp xếp theo cách bạn nghĩ.', '<button class="btn primary" data-note-new>+ Ghi chú</button>')+`<div class="notes-grid">${(data.notes||[]).filter(n=>(n.title+' '+n.text).toLowerCase().includes(query.toLowerCase())).map((n,i)=>`<article class="panel note" style="border-top:4px solid ${n.color}"><small>${esc(n.group||'Ý tưởng')}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.sketch?`<img class="note-sketch" alt="Phác thảo ghi chú" src="${n.sketch}">`:''}${n.url?`<a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">Mở tài liệu ↗</a>`:''}<div class="help-actions"><button class="btn" data-note-edit="${n.id}">Sửa</button><button class="btn" data-note-up="${i}">↑</button><button class="btn" data-note-down="${i}">↓</button><button class="btn danger" data-note-delete="${n.id}">Xóa</button></div></article>`).join('')}</div>`;}
function noteForm(n){modal('<h2>'+ (n?'Chỉnh ghi chú':'Ghi chú mới')+'</h2>'+field('Tiêu đề','title',n?.title||'','text',true,150)+field('Nhóm / bảng ý tưởng','group',n?.group||'','text',false,80)+`<label class="field">Nội dung<textarea name="text" maxlength="10000">${esc(n?.text||'')}</textarea></label>`+field('Liên kết tài liệu','url',n?.url||'','url',false,2000)+field('Màu thẻ','color',n?.color||'#7950c8','color')+'<p>Phác thảo nhanh</p><canvas id="note-canvas" width="640" height="320" aria-label="Vùng vẽ phác thảo"></canvas><button class="btn" type="button" id="clear-sketch">Xóa nét vẽ</button>',fd=>{const url=fd.get('url');if(url&&!/^https?:\/\//i.test(url))return notify('Liên kết cần bắt đầu bằng https:// hoặc http://');data.notes||=[];if(!n&&data.notes.length>=500)return notify('Tối đa 500 ghi chú.');const value={sketch:sketchDirty?$('#note-canvas').toDataURL('image/png'):(n?.sketch||''),title:fd.get('title').trim(),group:fd.get('group'),text:fd.get('text'),url,color:fd.get('color')};if(n)Object.assign(n,value);else data.notes.push({id:uid(),...value});save();$('#editor').close();render();});let sketchDirty=false;const canvas=$('#note-canvas'),ctx=canvas.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#7950c8';if(n?.sketch){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0);img.src=n.sketch;}let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*640/r.width,(e.clientY-r.top)*320/r.height];};canvas.onpointerdown=e=>{drawing=true;sketchDirty=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke();}};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;$('#clear-sketch').onclick=()=>{ctx.clearRect(0,0,640,320);sketchDirty=true;};}
function scheduleEvents(){return dueTasks().flatMap(t=>[{...t,eventStart:t.start||t.due,eventEnd:t.end||t.start||t.due},...t.checks.filter(c=>c.start||c.end).map(c=>({...t,title:t.title+' / '+c.text,eventStart:c.start||c.end,eventEnd:c.end||c.start}))]);}
workTimeline=function(){const tasks=scheduleEvents().sort((a,b)=>(a.eventStart||'9999').localeCompare(b.eventStart||'9999'));return heading('LỊCH CÔNG VIỆC','Timeline','Khoảng thời gian task và checklist · giờ Việt Nam')+workFilters()+'<section class="panel">'+tasks.map(t=>`<div class="timeline-item"><small>${esc((t.eventStart||'Chưa đặt lịch').replace('T',' '))} → ${esc((t.eventEnd||'').replace('T',' '))}</small>${timelineTask(t)}</div>`).join('')+'</section>';};
workCalendar=function(){const events=scheduleEvents(),count=new Date(calendarYear,calendarMonth+1,0).getDate();return heading('LỊCH CÔNG VIỆC','Calendar','Task và checklist theo khoảng thời gian · giờ Việt Nam')+workFilters()+`<div class="section-head"><button class="btn" data-month="-1">←</button><h2>${calendarMonth+1}/${calendarYear}</h2><button class="btn" data-month="1">→</button></div><div class="agenda">`+Array.from({length:count},(_,i)=>{const day=`${calendarYear}-${String(calendarMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,items=events.filter(t=>t.eventStart?.slice(0,10)<=day&&t.eventEnd?.slice(0,10)>=day);return items.length?`<section class="panel"><h3>${i+1}/${calendarMonth+1}</h3>${items.map(t=>`<small>${esc(t.eventStart?.slice(11)||'Cả ngày')} – ${esc(t.eventEnd?.slice(11)||'Cả ngày')}</small>${timelineTask(t)}`).join('')}</section>`:'';}).join('')+'</div>';};
async function filePanel(p,t){if(dirty){await flushCloud();if(dirty)return notify('Cần đồng bộ dự án trước khi gửi tệp.');}modal('<h2>Tệp & dữ liệu đính kèm</h2><p>Tệp tối đa 1 MB, tổng kho tài khoản 20 MB. Tải lên cần có mạng.</p><input id="upload-attachment" type="file" aria-label="Chọn tệp"><div id="attachment-list">Đang tải…</div>',null,true);const refresh=async()=>{const r=await requestAPI('files?project='+encodeURIComponent(p.id)+'&task='+encodeURIComponent(t?.id||''));$('#attachment-list').innerHTML=r.files.map(f=>`<p><a href="/api/files/${f.id}">${esc(f.name)}</a> · ${Math.ceil(f.size/1024)} KB</p>`).join('')||'<p>Chưa có tệp đính kèm.</p>';};try{await refresh();$('#upload-attachment').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1048576)return notify('Tối đa 1 MB mỗi tệp.');e.target.disabled=true;try{const raw=await file.arrayBuffer(),bytes=new Uint8Array(raw);let text='';for(const b of bytes)text+=String.fromCharCode(b);await requestAPI('files','POST',{project:p.id,task:t?.id||'',name:file.name,content:btoa(text)});await refresh();notify('Đã lưu tệp.');}catch(err){notify(err.message);}finally{e.target.disabled=false;}};}catch(err){$('#attachment-list').textContent=err.message;}}
for(const [v,label] of [['notes','Ghi chú'],['archive','Lưu trữ']]){const b=document.createElement('button');b.className='nav';b.dataset.view=v;b.innerHTML='<span>'+svgIcon(v)+'</span>'+label;document.querySelector('.sidebar nav').append(b);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-project-pin],[data-project-archive],[data-note-new],[data-note-edit],[data-note-delete],[data-note-up],[data-note-down],[data-check-time],[data-files]');if(!el)return;if(el.hasAttribute('data-project-pin')){const p=project(el.dataset.projectPin);p.pinned=!p.pinned;save();render();}if(el.hasAttribute('data-project-archive')){const p=project(el.dataset.projectArchive);if(!p.archived&&p.tasks.some(t=>t.col!=='Done'))return notify('Hoàn thành tất cả task trước khi lưu trữ dự án.');p.archived=!p.archived;save();go(p.archived?'archive':'projects',p.id);}if(el.hasAttribute('data-note-new'))noteForm();if(el.hasAttribute('data-note-edit'))noteForm(data.notes.find(n=>n.id===el.dataset.noteEdit));if(el.hasAttribute('data-note-delete'))confirmDelete('ghi chú',()=>{const id=el.dataset.noteDelete;data.notes=data.notes.filter(n=>n.id!==id);for(const n of data.notes)if(n.boardId===id)n.boardId='';});for(const key of ['noteUp','noteDown'])if(el.dataset[key]!==undefined){const i=Number(el.dataset[key]),j=i+(key==='noteUp'?-1:1);if(j>=0&&j<data.notes.length){[data.notes[i],data.notes[j]]=[data.notes[j],data.notes[i]];save();render();}}if(el.dataset.checkTime){const {p,t}=selected(),c=t.checks.find(c=>c.id===el.dataset.checkTime);modal('<h2>Lịch checklist</h2>'+scheduleFields(c),fd=>{const start=fd.get('start'),end=fd.get('end');if(start&&end&&start>end)return notify('Kết thúc phải sau bắt đầu.');Object.assign(c,{start,end});save();render();taskDetail(p,t);});}if(el.dataset.files)filePanel(project(el.dataset.files),project(el.dataset.files).tasks.find(t=>t.id===el.dataset.fileTask));});

render();
